struct string_buf { unsigned *data; int ref_count; int char_length; int block_length; int max_blocks; };
class stringx {
  char *chars;
  string_buf *my_buf;
public:
  stringx();
  stringx(const char *, int = -1);
  stringx(const stringx &);
  ~stringx();
  stringx &operator=(const stringx &);
  void make_room(int);
  void append(const stringx &);
  const char *c_str() const { return chars; }
  friend stringx operator+(const stringx &, const stringx &);
};
inline stringx operator+(const stringx &lhs, const stringx &rhs) {
  stringx foo;
  foo.make_room(lhs.my_buf->char_length + rhs.my_buf->char_length);
  foo.append(lhs);
  foo.append(rhs);
  return foo;
}
struct entity_id { unsigned value; };
