class entity {
  char p0[8];
  entity_vtable *vtable;
  char p1[108];
  unsigned flags;
  char p2[388];
public:
  entity(const stringx &, const entity_id &, entity_flavor_t, bool);
  void set_flag(unsigned f, bool set) { if (set) flags |= f; else flags &= ~f; }
  void set_active(bool v) { entity_vtable *t=vtable; t->active((char*)this+t->active_adj,v); }
  void set_stationary(bool v) { entity_vtable *t=vtable; t->stationary((char*)this+t->stationary_adj,v); }
  void set_walkable(bool v) { entity_vtable *t=vtable; t->walkable((char*)this+t->walkable_adj,v); }
  void set_repulsion(bool v) { entity_vtable *t=vtable; t->repulsion((char*)this+t->repulsion_adj,v); }
  void set_visible(bool v) { entity_vtable *t=vtable; t->visible((char*)this+t->visible_adj,v); }
};
